static const z_t6287_t _zag1657 = { { .data = "win_seek", .size = 8 }, { .length = 1, .data = _zag1656 }, { .length = 0, .data = NULL }, { .data = "/* `whence` is SEEK_SET, SEEK_CUR or SEEK_END, which are FILE_BEGIN,\n   FILE_CURRENT and FILE_END's values */\nstatic int64_t z_win_seek(int fd, int64_t off, int whence) {\n    LARGE_INTEGER d;\n    LARGE_INTEGER at;\n    d.QuadPart = off;\n    if (!SetFilePointerEx((HANDLE)_get_osfhandle(fd), d, &at, (DWORD)whence)) return -1;\n    return (int64_t)at.QuadPart;\n}", .size = 359 } };
