static const z_t6287_t _zag1832 = { { .data = "typeof", .size = 6 }, { .length = 1, .data = _zag1831 }, { .length = 0, .data = NULL }, { .data = "/* Z_TYPEOF -- the type of an expression, which the emitter names only for a\n   temporary whose type it has no C text for. ISO C17 has no spelling for it:\n   gcc, clang, tcc and MSVC take __typeof__ in C17 mode, and C23 standardises\n   it as typeof. */\n#if defined(__STDC_VERSION__) && __STDC_VERSION__ >= 202311L\n#define Z_TYPEOF(x) typeof(x)\n#else\n#define Z_TYPEOF(x) __typeof__(x)\n#endif", .size = 390 } };
static const z_t60_t _zag1833[] = {{ .data = "@value_typeof", .size = 13 }};

static const z_t6287_t _zag1834 = { { .data = "value_typeof", .size = 12 }, { .length = 1, .data = _zag1833 }, { .length = 0, .data = NULL }, { .data = "/* Z_VALUE_TYPEOF -- the unqualified type of an expression's value, for a\n   temporary the emitter declares first and assigns after: a `const` source\n   must still give an assignable temp. gcc, clang and tcc drop an rvalue's\n   qualifiers, which a comma makes of any operand; MSVC keeps them, and takes\n   __typeof_unqual__ instead. C23 names it typeof_unqual. */\n#if defined(__STDC_VERSION__) && __STDC_VERSION__ >= 202311L\n#define Z_VALUE_TYPEOF(x) typeof_unqual(x)\n#elif defined(_MSC_VER) && !defined(__clang__)\n#define Z_VALUE_TYPEOF(x) __typeof_unqual__(x)\n#else\n#define Z_VALUE_TYPEOF(x) __typeof__(((void)0, x))\n#endif", .size = 625 } };
static const z_t6287_t _zag1835 = { { .data = "", .size = 0 }, { .length = 0, .data = NULL }, { .length = 0, .data = NULL }, { .data = "\n/* z_clz64, z_ctz64, z_popcount64 -- the leading zeros, trailing zeros and set\n   bits of a 64-bit word. v must not be 0 for the first two, as for the\n   builtins they stand for. gcc, clang and tcc take their builtins; MSVC has\n   none, and takes the bit-scan intrinsics and a portable count of set bits\n   (__popcnt64 needs a processor with POPCNT, which MSVC does not test for). */", .size = 384 } };
static const z_t60_t _zag1836[] = {{ .data = "@clz64", .size = 6 }};

static const z_t6287_t _zag1837 = { { .data = "clz64", .size = 5 }, { .length = 1, .data = _zag1836 }, { .length = 0, .data = NULL }, { .data = "#if defined(_MSC_VER) && !defined(__clang__)\n#include <intrin.h>\nstatic inline int z_clz64(uint64_t v) {\n    unsigned long i;\n    _BitScanReverse64(&i, v);\n    return 63 - (int)i;\n}\n#else\n#define z_clz64(v) __builtin_clzll(v)\n#endif", .size = 232 } };
static const z_t60_t _zag1838[] = {{ .data = "@ctz64", .size = 6 }};

static const z_t6287_t _zag1839 = { { .data = "ctz64", .size = 5 }, { .length = 1, .data = _zag1838 }, { .length = 0, .data = NULL }, { .data = "#if defined(_MSC_VER) && !defined(__clang__)\n#include <intrin.h>\nstatic inline int z_ctz64(uint64_t v) {\n    unsigned long i;\n    _BitScanForward64(&i, v);\n    return (int)i;\n}\n#else\n#define z_ctz64(v) __builtin_ctzll(v)\n#endif", .size = 227 } };
static const z_t60_t _zag1840[] = {{ .data = "@popcount64", .size = 11 }};

static const z_t6287_t _zag1841 = { { .data = "popcount64", .size = 10 }, { .length = 1, .data = _zag1840 }, { .length = 0, .data = NULL }, { .data = "#if defined(_MSC_VER) && !defined(__clang__)\nstatic inline int z_popcount64(uint64_t v) {\n    v = v - ((v >> 1) & 0x5555555555555555u);\n    v = (v & 0x3333333333333333u) + ((v >> 2) & 0x3333333333333333u);\n    v = (v + (v >> 4)) & 0x0F0F0F0F0F0F0F0Fu;\n    return (int)((v * 0x0101010101010101u) >> 56);\n}\n#else\n#define z_popcount64(v) __builtin_popcountll(v)\n#endif", .size = 365 } };
